<?php
namespace App\Catalog;
use Symfony\Contracts\HttpClient\HttpClientInterface;
final class TvMazeCatalogProvider implements SeriesCatalogProvider { public function __construct(private HttpClientInterface $client){} public function name():string{return 'tvmaze';} public function search(string $query):array{$data=$this->request('/search/shows',['q'=>$query]);return array_map(fn(array $r)=>$this->normalize($r['show']),$data);} public function fetch(string $id):array{return $this->request('/shows/'.$id.'?embed[]=seasons&embed[]=episodes&embed[]=cast');} public function fetchCast(string $id):array{return $this->request('/shows/'.$id,['embed'=>'cast']);} public function rawSearch(string $query):array{return $this->request('/search/shows',['q'=>$query]);} public function rawShow(string $id):array{return $this->request('/shows/'.$id,['embed'=>['seasons','episodes','cast','crew','images']]);} public function rawCast(string $id):array{return $this->fetchCast($id);} private function request(string $path,array $query=[]):array{$response=$this->client->request('GET','https://api.tvmaze.com'.$path,['query'=>$query,'headers'=>['Accept'=>'application/json','User-Agent'=>'ZunaTrack/1.0']]);return $response->toArray();} private function normalize(array $show):array{return ['id'=>(string)$show['id'],'title'=>$show['name'],'summary'=>isset($show['summary'])?strip_tags((string)$show['summary']):null,'posterUrl'=>$show['image']['medium']??null,'premiered'=>$show['premiered']??null];} }
